namespace Model.Services.Portal { public class ToplantiParametreService { private readonly ToplantiParametreRepository r; public ToplantiParametreService():this(new ToplantiParametreRepository()){} public ToplantiParametreService(ToplantiParametreRepository r){if(r==null)throw new ArgumentNullException("r");this.r=r;} public ToplantiParametre GetById(int id){return Map(r.SelectById(id));} public List<ToplantiParametre> GetAll(){return List(r.SelectAll());} public List<ToplantiParametre> GetByGroup(string g){return List(r.SelectByGroup(g));} public List<ToplantiParametre> GetUnselected(string g){return List(r.SelectByGroupUnselected(g));} public List<ToplantiParametre> GetSelected(string g){return List(r.SelectByGroupSelected(g));} public DataTable GetAllData(){return r.SelectAllData();} public List<ToplantiParametre> GetByGroupValue(string g,string d){return List(r.SelectByGroupValue(g,d));} public int Save(ToplantiParametre x){if(x==null)throw new ArgumentNullException("x");x.OlusturmaTarihi=DateTime.Now;x.Id=r.Insert(x);return x.Id;} public bool Update(ToplantiParametre x){if(x==null||x.Id==0)return false;x.DegistirmeTarihi=DateTime.Now;return r.Update(x);} public bool Delete(ToplantiParametre x){return x!=null&&x.Id!=0&&r.Delete(x.Id);} private static List<ToplantiParametre> List(DataTable t){return new ToplantiParametre().ToList<ToplantiParametre>(t);} private static ToplantiParametre Map(DataTable t){return List(t).FirstOrDefault();} } }
